function [source, signal_info, delays] = create_source( ...
    focal_point_grid, row_counts, element_height, element_width, element_pitch, ...
    source_amp, sample_freq, source_f0, c0, kgrid, varargin)
%CREATE_SOURCE Model the 256-element Fraunhofer TRUST transducer.
%
% The array geometry and the per-element delays are defined here, while the
% temporal excitation is generated by create_signal. Elements are focused
% geometrically on focal_point_grid using the homogeneous sound speed c0.
%
% 'PACDelay' takes one phase-aberration-correction delay [s] per element, as
% returned by estimate_pac_phase_reversal. If it is omitted or given as [],
% only geometric focusing is applied. All other name-value arguments are
% forwarded to create_signal ('NumCycles', 'PulseDuration', 'PRFPeriod',
% 'NumPulsesPerTrain', ...), in any order:
%
%   create_source(..., kgrid, 'NumCycles', 30);
%   create_source(..., kgrid, 'PACDelay', pac_delay, 'NumCycles', 30);
%   create_source(..., kgrid, 'NumCycles', 30, 'PACDelay', pac_delay);
%
% author: Maylis Mueller
% date:
% last update:

    % optional inputs
    % PACDelay is consumed here; every other pair is kept in order and passed
    % on to create_signal, which reports any name it does not recognise.
    pac_delay   = [];
    signal_args = {};

    if mod(numel(varargin), 2) ~= 0
        error('Name-value arguments must come in pairs.');
    end

    for a = 1:2:numel(varargin)
        if strcmpi('PACDelay', varargin{a})
            pac_delay = varargin{a+1};
        else
            signal_args(end+1:end+2) = varargin(a:a+1);
        end
    end

    % array
    z_pos = kgrid.z_vec(1);
    [karray, ~] = build_karray(row_counts, element_height, element_width, ...
                               element_pitch, z_pos);

    source.p_mask = karray.getArrayBinaryMask(kgrid);
    num_elements  = numel(karray.elements);

    % geometric focusing delays
    travel_time = zeros(1, num_elements);

    for n = 1:num_elements
        pos = karray.elements{n}.position;
        travel_time(n) = norm(pos - focal_point_grid) / c0;
    end

    geometric_delay = max(travel_time) - travel_time;

    % optional PAC delays
    if isempty(pac_delay)
        pac_delay = zeros(1, num_elements);
    else
        pac_delay = pac_delay(:).';
        if numel(pac_delay) ~= num_elements
            error('PACDelay must contain one value for each of the %d elements.', ...
                  num_elements);
        end
    end

    % total delays, shifted so the earliest element starts at t = 0
    total_delay   = geometric_delay + pac_delay;
    total_delay   = total_delay - min(total_delay);
    delay_samples = round(total_delay .* sample_freq);

    % temporal signal
    [base_signal, signal_info] = create_signal(sample_freq, source_f0, ...
                                               source_amp, kgrid.Nt, signal_args{:});

    % apply delays
    % Samples pushed past the end of the time array are dropped, so t_end must
    % accommodate the largest delay plus the signal duration.
    source_sig = zeros(num_elements, kgrid.Nt);

    for n = 1:num_elements
        d = delay_samples(n);
        N_remaining = kgrid.Nt - d;
        if N_remaining <= 0
            continue;
        end
        source_sig(n, d + (1:N_remaining)) = base_signal(1:N_remaining);
    end

    source.p = karray.getDistributedSourceSignal(kgrid, source_sig);

    % delay information
    delays.geometric = geometric_delay;
    delays.pac       = pac_delay;
    delays.total     = total_delay;
    delays.samples   = delay_samples;
end